// UpdatedAtLTE applies the LTE predicate on the "updated_at" field.
func UpdatedAtLTE(v time.Time) predicate.HRDetails {
	return predicate.HRDetails(sql.FieldLTE(FieldUpdatedAt, v))
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.HRDetails) predicate.HRDetails {
	return predicate.HRDetails(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.HRDetails) predicate.HRDetails {
	return predicate.HRDetails(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.HRDetails) predicate.HRDetails {
	return predicate.HRDetails(sql.NotPredicates(p))
}
